INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2201387', 'Franco-Monegasque Treaty', 'The Franco-Monégasque Treaties of 1861, 1918, and 2002 are the basis of the relationship between France and Monaco. The treaties define Monaco''s independent status and sovereignty, as well as the rights of succession of the princely House of Grimaldi.', 1861, NULL, NULL, NULL, NULL, NULL, 'year', '1861', 48, 'https://en.wikipedia.org/wiki/Franco-Mon%C3%A9gasque_Treaties'),
